import{_ as t,o as a,c as i,a9 as r}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Documentation guide","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/documentation.md","filePath":"contributing/documentation.md","lastUpdated":null}'),s={name:"contributing/documentation.md"};function n(o,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="Documentation-guide" tabindex="-1">Documentation guide <a class="header-anchor" href="#Documentation-guide" aria-label="Permalink to &quot;Documentation guide {#Documentation-guide}&quot;">​</a></h1><p>Documentation contributions are welcome, from fixing an unclear sentence to adding a reproducible example. Use <strong>Edit this page</strong> to suggest a change, or <a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/issues" target="_blank" rel="noreferrer">open an issue</a> with the page address and the step that was difficult to follow.</p><h2 id="Write-for-someone-trying-the-tool" tabindex="-1">Write for someone trying the tool <a class="header-anchor" href="#Write-for-someone-trying-the-tool" aria-label="Permalink to &quot;Write for someone trying the tool {#Write-for-someone-trying-the-tool}&quot;">​</a></h2><p>Introduce the operation before its configuration. Show a runnable example, then explain what the code does and how to read its output. The Julia manual&#39;s <a href="https://docs.julialang.org/en/v1.14-dev/manual/profile/" target="_blank" rel="noreferrer">profiling chapter</a> is a useful example of this sequence.</p><p>Use familiar names and concrete statements: “The worker times <code>operation</code>” is clearer than “The lifecycle preserves the measurement boundary.” Explain technical terms when they are needed. Keep limitations beside the operation or result they affect, rather than repeating general warnings in every section.</p><p>Use <a href="./../tutorials/quick-tour">Bibliography</a>, <a href="./../real-packages/datastructures">DataStructures</a> or <a href="./../real-packages/oxygen">Oxygen</a> for examples. Put a plot beside each measured comparison, explain its axes and discuss the values readers can see. Link to a reference for additional options. Keep work notes and proposed features outside the user guides.</p><h2 id="Local-build" tabindex="-1">Local build <a class="header-anchor" href="#Local-build" aria-label="Permalink to &quot;Local build {#Local-build}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=website</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; cd(&quot;website&quot;) do; Pkg.develop(path=&quot;..&quot;); Pkg.instantiate(); end&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website/make.jl</span></span></code></pre></div><p>Install Node.js 22.12 or newer first. The build uses the system Node runtime and writes the static site to <code>website/build/site</code>. DocumenterVitepress writes intermediate Markdown; the explicit VitePress step makes a missing Windows HTML build fail. Building never deploys. The independent documentation workflow publishes development pages after building them. Package qualification runs separately and never blocks documentation publication.</p><p>Run <code>node website/preview.mjs</code> to browse the completed site locally. The preview keeps a snapshot so another build cannot interrupt readers. Restart the preview after a successful build to display its new pages.</p><p>The build rejects missing references and dead links. The core test suite checks that every exported binding is defined and documented. Review the content too: an existing docstring is not proof that its arguments and guarantees are correct.</p><h2 id="Information-architecture" tabindex="-1">Information architecture <a class="header-anchor" href="#Information-architecture" aria-label="Permalink to &quot;Information architecture {#Information-architecture}&quot;">​</a></h2><ul><li><p><strong>Manual</strong> follows Bibliography from a test to an operation benchmark, then explains the results, suites, comparisons, profiling and CI. Each chapter continues the previous one; its ending points to the next operation.</p></li><li><p><strong>Examples</strong> develops complete experiments for Bibliography, DataStructures and Oxygen, with saved measurements and runnable notebooks.</p></li><li><p><strong>Interfaces</strong> describes the controls and setup for each UI.</p></li><li><p><strong>Further topics</strong> covers additional measurements, larger experiments, remote execution and optional advisors.</p></li><li><p><strong>Reference</strong> documents arguments, formats and integration details.</p></li><li><p><strong>Contributing</strong> covers architecture, collection tests and documentation.</p></li></ul><p>Keep each detailed explanation in one place and link to it from other pages. The sidebar and previous/next links come from <code>website/make.jl</code>; update their order when moving a chapter. Follow the approaches used by the <a href="https://docs.julialang.org/en/v1.14-dev/" target="_blank" rel="noreferrer">Julia manual</a>, <a href="https://jump.dev/JuMP.jl/stable/tutorials/getting_started/getting_started_with_JuMP/" target="_blank" rel="noreferrer">JuMP tutorials</a> and <a href="https://juliaconstraints.github.io/dev/cp/30_getting_started" target="_blank" rel="noreferrer">Julia Constraints introduction</a>: introduce a problem, add the concepts needed to solve it, and inspect the result.</p><p>Before adding a code block, say whether it is a complete runnable example, a fragment using earlier variables, or a format illustration. Give the working directory, prerequisites and expected output. Name placeholder paths explicitly. Link to the step that creates an input file before asking the reader to use it.</p><p>Do not duplicate feature claims across pages without linking to the canonical reference. Never present a planned collector, platform, or attribution method as implemented.</p><h2 id="Explain-a-measurement-before-configuring-it" tabindex="-1">Explain a measurement before configuring it <a class="header-anchor" href="#Explain-a-measurement-before-configuring-it" aria-label="Permalink to &quot;Explain a measurement before configuring it {#Explain-a-measurement-before-configuring-it}&quot;">​</a></h2><p>Introduce every collector with one or two paragraphs explaining the question it answers, the quantity and unit it records, and how to read the result. Define terms such as wall time, GC and flame graph at first use or link directly to the <a href="./../guide/understanding-measurements">measurement tutorial</a>. A table of option names alone is not an introduction.</p><p>Use Bibliography for the worked examples. Version comparisons must contain several actual revisions, with input and dependency provenance; a distribution from one version only demonstrates sampling variation. Distinguish declared package versions, Git tags and later commits. Explain unavailable workloads and failed preparation without replacing them with zero-valued measurements.</p><p>When two collectors expose similarly named fields, explain their differences locally: BenchmarkTools GC time and Chairmarks GC fraction have different units, and CPU samples, task wall-time stacks and elapsed benchmark times answer different questions. Add a reading paragraph beside an interactive plot so the reader can interpret it without opening a separate reference page.</p><h2 id="Screenshot-policy" tabindex="-1">Screenshot policy <a class="header-anchor" href="#Screenshot-policy" aria-label="Permalink to &quot;Screenshot policy {#Screenshot-policy}&quot;">​</a></h2><p>Store images under <code>website/src/public/assets/screenshots/&lt;interface&gt;/</code> or a similarly specific folder. Use actual application output only—never a fabricated UI—and:</p><ol><li><p>capture a fixed, readable desktop size and an additional narrow layout when responsive behavior matters;</p></li><li><p>remove tokens, private endpoints, usernames, local absolute paths, and private package data;</p></li><li><p>use stable demo bundles so screenshots can be regenerated;</p></li><li><p>provide descriptive alt text and a caption that explains the user outcome;</p></li><li><p>prefer SVG for diagrams, PNG/WebP for UI, and static Makie export for plots;</p></li><li><p>verify both light and dark themes when the component supports them;</p></li><li><p>refresh images when labels or flows change, not merely on every release.</p></li></ol><p>Use the <code>doc-screenshot</code> figure class for consistent borders and captions.</p><p>The lightweight figures beside the tutorials are generated from the public recorded JSON files. To regenerate them, install the optional plotting dependency and run the exporter from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website/scripts/plot-requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website/scripts/render-measured-plots.py</span></span></code></pre></div><p>This redraws saved measurements without launching benchmarks. The exporter records its input digests in <code>examples/bibliography/figures/provenance.json</code> under the site&#39;s public directory. Interactive Makie exports remain separate; their own download links contain the same historical measurements.</p><h2 id="Recordings-outside-Git" tabindex="-1">Recordings outside Git <a class="header-anchor" href="#Recordings-outside-Git" aria-label="Permalink to &quot;Recordings outside Git {#Recordings-outside-Git}&quot;">​</a></h2><p>Keep source recordings outside the Git history. The local archive is <code>.lab/media/&lt;recording&gt;/</code>; <code>website/.gitignore</code> also excludes WebM, MP4 and MOV copies used by the preview. Screenshots, captions, the written walkthrough and <code>website/media.json</code> remain versioned. The catalogue records the original file&#39;s byte count and SHA-256 digest.</p><p>For publication, use an approved project recording on YouTube for the embedded player. Set the recording&#39;s <code>youtube_id</code> in <code>website/media.json</code> after uploading and reviewing the video and its captions. The site loads the privacy-enhanced YouTube player only after the reader clicks its poster. This mode does not make YouTube a tracker-free service; see the <a href="https://support.google.com/youtube/answer/171780?hl=en" target="_blank" rel="noreferrer">YouTube embedding documentation</a>.</p><p>The Bibliography originals and English captions are available in the <a href="https://github.com/Mirage-Interactive-Fr/Mirage-Interactive-Fr.github.io/releases/tag/documentation-media-v1" target="_blank" rel="noreferrer">documentation recordings release</a>. Attach further originals to a GitHub Release and put its HTTPS URL in <code>download_url</code>. Release attachments distribute binaries separately from the Git history. GitHub Actions artifacts are useful for temporary test captures, but their retention period makes them unsuitable as permanent documentation media. See <a href="https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases" target="_blank" rel="noreferrer">GitHub releases</a> and <a href="https://docs.github.com/en/organizations/managing-organization-settings/configuring-the-retention-period-for-github-actions-artifacts-and-logs-in-your-organization" target="_blank" rel="noreferrer">artifact retention</a>.</p><p>Until the video is published, a local build can read an ignored copy at the catalogue&#39;s <code>file</code> path beneath <code>website/src/public/</code>. The build verifies its size and digest. A clean checkout without that file shows the poster and a written-walkthrough fallback, with no broken video request. The browser tests check whichever state the build actually contains; they do not claim to test YouTube playback when no published video is configured.</p><p>The opt-in <code>qualification/shared/bibliography-web.mjs</code> script records a real run; the ordinary documentation tests replay its video without launching Julia measurement workers. Neither workflow uploads media or publishes the site.</p><h2 id="Pull-request-checklist" tabindex="-1">Pull-request checklist <a class="header-anchor" href="#Pull-request-checklist" aria-label="Permalink to &quot;Pull-request checklist {#Pull-request-checklist}&quot;">​</a></h2><ul><li><p>build DocumenterVitepress locally;</p></li><li><p>check internal and external links;</p></li><li><p>run doctests and package TestItems affected by examples;</p></li><li><p>verify screenshots at their rendered size;</p></li><li><p>scan for stale organization/repository identities;</p></li><li><p>state which commands passed and which optional integrations were not exercised.</p></li></ul>`,35)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
